<template>
  <div class="game-wrapper">
    <div class="game-container">
      <div class="config-panel">
        <div class="config-row config-row-top">
          <div class="config-item">
            <label>网格大小</label>
            <input
              v-model.number="tempGridCols"
              type="number"
              min="10"
              max="64"
              @change="tempGridCols = clampInt(tempGridCols, 10, 64)"
            />
            <span class="x-sign">×</span>
            <input
              v-model.number="tempGridRows"
              type="number"
              min="10"
              max="64"
              @change="tempGridRows = clampInt(tempGridRows, 10, 64)"
            />
          </div>

          <div class="config-item">
            <label>选曲数量</label>
            <input
              v-model.number="gameSongCount"
              type="number"
              min="1"
              max="256"
              @change="gameSongCount = clampInt(gameSongCount, 1, 256, 5)"
            />
          </div>
        </div>

        <div class="config-row config-row-bottom">
          <div class="config-checks">
            <div class="config-item check-item">
              <label>非英文曲名</label>
              <input v-model="allowNonEnglish" type="checkbox" />
            </div>
            <div class="config-item check-item">
              <label>字母全大写</label>
              <input v-model="ignoreCase" type="checkbox" />
            </div>
          </div>

          <div class="btn-group-right">
            <button class="gen-btn" @click="generatePuzzle" :disabled="isGenerating || !songList.length">
              {{ isGenerating ? '生成中…' : '生成字谜' }}
            </button>
            <button class="save-btn" @click="saveQuestionImage" :disabled="!questionImageUrl">
              下载题目
            </button>
            <button class="save-btn" @click="saveAnswerImage" :disabled="!answerImageUrl">
              下载答案
            </button>
          </div>
        </div>
      </div>

      <div class="main-content">
        <div
            class="grid-scroll-wrap"
            @mousedown="handleMouseDown"
            @mousemove="handleMouseMove"
            @mouseup="handleMouseUp"
            @mouseleave="handleMouseUp"
        >
          <div
            ref="gridRef"
            class="grid"
            :style="{
              gridTemplateColumns: `repeat(${gridCols}, 1fr)`,
            }"
          >
            <div v-for="(cell, idx) in gridList" :key="idx" class="cell">
              {{ cell.letter }}
            </div>
          </div>
        </div>

        <div
            class="answer-scroll-wrap"
            @mousedown="handleMouseDown"
            @mousemove="handleMouseMove"
            @mouseup="handleMouseUp"
            @mouseleave="handleMouseUp"
        >
          <div
            class="answer-grid"
            :style="{
              gridTemplateColumns: `repeat(${gridCols}, 1fr)`,
            }"
          >
            <div
              v-for="(cell, idx) in answerGridList"
              :key="idx"
              class="answer-cell"
              :style="{ background: cell.color }"
            >
              {{ cell.letter }}
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- 题目截图容器：统一加上白色半透明背景 -->
    <div ref="questionWrapRef" class="image-wrap-hidden">
      <div class="grid-image-container">
        <div class="grid-image" :style="{ gridTemplateColumns: `repeat(${gridCols}, 1fr)` }">
          <div 
            v-for="(cell, idx) in gridList" 
            :key="idx" 
            class="cell-image"
            style="background:rgba(255,255,255,0.08);"
          >
            {{ cell.letter }}
          </div>
        </div>
      </div>
    </div>

    <!-- 答案截图容器 -->
    <div ref="answerWrapRef" class="image-wrap-hidden">
      <div class="grid-image-container">
        <div class="grid-image" :style="{ gridTemplateColumns: `repeat(${gridCols}, 1fr)` }">
          <div 
            v-for="(cell, idx) in answerGridList" 
            :key="idx" 
            class="cell-image" 
            :style="{ background: cell.color }"
          >
            {{ cell.letter }}
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch, onMounted, nextTick } from 'vue'
import html2canvas from 'html2canvas'

const directions = [
  [0, 1],
  [1, 0],
  [1, 1]
]

const COLORS = [
  'rgba(59, 130, 246, 0.25)',
  'rgba(16, 185, 129, 0.25)',
  'rgba(245, 158, 11, 0.25)',
  'rgba(239, 68, 68, 0.25)',
  'rgba(168, 85, 247, 0.25)',
  'rgba(217, 70, 239, 0.25)',
  'rgba(237, 137, 54, 0.25)',
  'rgba(82, 183, 136, 0.25)',
  'rgba(21, 122, 112, 0.25)',
  'rgba(79, 70, 229, 0.25)',
  'rgba(236, 72, 153, 0.25)',
  'rgba(234, 88, 12, 0.25)',
  'rgba(217, 119, 6, 0.25)',
  'rgba(132, 204, 22, 0.25)',
  'rgba(14, 165, 233, 0.25)',
  'rgba(99, 102, 241, 0.25)',
  'rgba(249, 115, 22, 0.25)',
  'rgba(251, 191, 36, 0.25)',
  'rgba(134, 239, 172, 0.25)',
  'rgba(125, 211, 252, 0.25)',
  'rgba(196, 181, 253, 0.25)',
  'rgba(241, 156, 186, 0.25)',
  'rgba(127, 29, 29, 0.25)',
  'rgba(46, 125, 50, 0.25)',
  'rgba(26, 35, 126, 0.25)',
  'rgba(121, 40, 113, 0.25)',
]

const props = defineProps({
  songList: {
    type: Array,
    default: () => []
  }
})

const tempGridCols = ref(10)
const tempGridRows = ref(10)
const gridCols = ref(10)
const gridRows = ref(10)
const gameSongCount = ref(5)
const allowNonEnglish = ref(false)
const ignoreCase = ref(false)

const grid = ref([])
const gridList = ref([])
const placements = ref([])
const gameSongs = ref([])
const songCharSet = ref(new Set())
const answerGridList = ref([])

const isGenerating = ref(false)

const questionImageUrl = ref('')
const answerImageUrl = ref('')
const imageTimestamp = ref('')

const gridRef = ref(null)
const questionWrapRef = ref(null)
const answerWrapRef = ref(null)

const isDragging = ref(false)
const dragEl = ref(null)
const startX = ref(0)
const startY = ref(0)
const scrollLeft = ref(0)
const scrollTop = ref(0)

// 输入框失焦 / 回车时才夹紧数值：边输入边改写会让「50」这种两位数根本打不进去，
// 同时也兜住手输超范围（例如直接输 999）导致生成超大网格把页面卡死的情况
function clampInt(value, min, max, fallback = min) {
  const n = Math.round(Number(value))
  if (!Number.isFinite(n)) return fallback
  return Math.min(max, Math.max(min, n))
}

function handleMouseDown(e) {
  isDragging.value = true
  dragEl.value = e.currentTarget
  startX.value = e.pageX
  startY.value = e.pageY
  scrollLeft.value = e.currentTarget.scrollLeft
  scrollTop.value = e.currentTarget.scrollTop
  e.preventDefault()
}
function handleMouseMove(e) {
  // 只让「按下时的那一块」跟着拖动，避免拖过中线时题目和答案一起跳（光标样式由 CSS 的 :active 负责）
  if (!isDragging.value || e.currentTarget !== dragEl.value) return
  const dx = e.pageX - startX.value
  const dy = e.pageY - startY.value
  e.currentTarget.scrollLeft = scrollLeft.value - dx
  e.currentTarget.scrollTop = scrollTop.value - dy
}
function handleMouseUp() {
  isDragging.value = false
  dragEl.value = null
}

function cleanName(name) {
  if (!name) return ''
  let res = name

  if (!allowNonEnglish.value) {
    res = res.replace(/[^a-zA-Z0-9]/g, '')
  }
  else {
    res = res.replace(/\s/g, '')
  }

  if (ignoreCase.value) res = res.toUpperCase()
  return res.trim()
}

function getValidSongs(list) {
  const maxLen = Math.min(gridCols.value, gridRows.value) - 1
  const res = []
  list.forEach(item => {
    const clean = cleanName(item.name)
    if (clean && clean.length >= 2 && clean.length <= maxLen) {
      res.push({ raw: item, clean })
    }
  })
  return res
}

function pickSongs(validList, count) {
  const shuffled = [...validList].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, Math.min(count, validList.length))
}

function generateFullGrid(words) {
  let bestGrid = []
  let bestPlacements = []
  let bestCount = 0
  const targetCount = words.length

  for (let attempt = 0; attempt < 100; attempt++) {
    const g = Array(gridRows.value).fill().map(() => Array(gridCols.value).fill(''))
    const placed = []

    words.forEach(word => {
      const w = word.clean
      const len = w.length
      let placedOne = false

      for (let i = 0; i < 50; i++) {
        const r = Math.floor(Math.random() * gridRows.value)
        const c = Math.floor(Math.random() * gridCols.value)
        const [dr, dc] = directions[Math.floor(Math.random() * directions.length)]
        const er = r + dr * (len - 1)
        const ec = c + dc * (len - 1)
        if (er >= gridRows.value || ec >= gridCols.value) continue

        let ok = true
        for (let j = 0; j < len; j++) {
          const nr = r + dr * j
          const nc = c + dc * j
          if (g[nr][nc] && g[nr][nc] !== w[j]) { ok = false; break }
        }
        if (ok) {
          for (let j = 0; j < len; j++) {
            const nr = r + dr * j
            const nc = c + dc * j
            g[nr][nc] = w[j]
          }
          placed.push({ word: w, r, c, dr, dc })
          placedOne = true
          break
        }
      }
    })

    if (placed.length > bestCount) {
      bestCount = placed.length
      bestGrid = JSON.parse(JSON.stringify(g))
      bestPlacements = [...placed]
    }
    
    if (bestCount === targetCount) break
  }

  const chars = Array.from(songCharSet.value)
  const fill = chars.length ? chars : ['A', 'B', 'C', 'D', 'E']

  for (let i = 0; i < gridRows.value; i++) {
    for (let j = 0; j < gridCols.value; j++) {
      if (!bestGrid[i][j]) bestGrid[i][j] = fill[Math.floor(Math.random() * fill.length)]
    }
  }

  return { grid: bestGrid, placements: bestPlacements }
}

function renderAnswerGrid(placed) {
  const list = []
  for (let i = 0; i < gridRows.value; i++) {
    for (let j = 0; j < gridCols.value; j++) {
      list.push({ letter: grid.value[i][j], color: 'rgba(255,255,255,0.08)' })
    }
  }

  placed.forEach((p, idx) => {
    const color = COLORS[idx % COLORS.length]
    const len = p.word.length
    for (let j = 0; j < len; j++) {
      const r = p.r + p.dr * j
      const c = p.c + p.dc * j
      list[r * gridCols.value + c].color = color
    }
  })

  answerGridList.value = list
}

async function initGame(list) {
  if (!list.length) return

  gridCols.value = clampInt(tempGridCols.value, 10, 64, 10)
  gridRows.value = clampInt(tempGridRows.value, 10, 64, 10)

  grid.value = []
  placements.value = []
  gameSongs.value = []
  songCharSet.value.clear()
  questionImageUrl.value = ''
  answerImageUrl.value = ''

  const validList = getValidSongs(list)
  const selected = pickSongs(validList, clampInt(gameSongCount.value, 1, 256, 5))

  selected.forEach(s => {
    for (const c of s.clean) songCharSet.value.add(c)
  })

  const { grid: g, placements: p } = generateFullGrid(selected)
  grid.value = g
  placements.value = p
  gameSongs.value = selected

  flattenGrid()
  renderAnswerGrid(p)
  
  await createAllImages()
}

function flattenGrid() {
  const list = []
  for (let i = 0; i < gridRows.value; i++) {
    for (let j = 0; j < gridCols.value; j++) {
      list.push({ letter: grid.value[i][j] })
    }
  }
  gridList.value = list
}

async function createAllImages() {
  imageTimestamp.value = new Date().getTime().toString()
  await nextTick()
  if (questionWrapRef.value) {
    const canvas1 = await html2canvas(questionWrapRef.value, { useCORS: true, scale: 2, backgroundColor: '#494949' })
    questionImageUrl.value = canvas1.toDataURL('image/png')
  }
  if (answerWrapRef.value) {
    const canvas2 = await html2canvas(answerWrapRef.value, { useCORS: true, scale: 2, backgroundColor: '#494949' })
    answerImageUrl.value = canvas2.toDataURL('image/png')
  }
}

async function generatePuzzle() {
  if (isGenerating.value) return
  isGenerating.value = true
  try {
    await initGame(props.songList)
  } finally {
    isGenerating.value = false
  }
}

function saveQuestionImage() {
  if (!questionImageUrl.value) return
  const a = document.createElement('a')
  a.download = `题目_${imageTimestamp.value}.png`
  a.href = questionImageUrl.value
  a.click()
}

function saveAnswerImage() {
  if (!answerImageUrl.value) return
  const a = document.createElement('a')
  a.href = answerImageUrl.value
  a.download = `答案_${imageTimestamp.value}.png`
  a.click()
}

watch(() => props.songList, val => initGame(val), { deep: true })
onMounted(() => initGame(props.songList))
</script>

<style scoped>
.game-wrapper {
  width: 100%;
  background: var(--color-bg-main);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.3rem;
  margin-top: 0.3rem;
  box-sizing: border-box;
  user-select: none;
}

.game-container {
  width: 100%;
  max-width: 100%;
  display: flex;
  flex-direction: column;
}

.config-panel {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  padding: 0.25rem;
}

.config-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.25rem;
}

.config-row-top {
  justify-content: flex-start;
}

.config-row-bottom {
  justify-content: space-between;
}

.config-checks {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.config-item {
  display: flex;
  align-items: center;
  gap: 0.1rem;
  font-size: 0.18rem;
  color: var(--color-text);
  white-space: nowrap;
}

.config-item input {
  width: 0.8rem;
  padding: 0.08rem 0.14rem;
  font-size: 0.18rem;
  background: var(--color-bg-sub);
  color: var(--color-text);
  border: 0.01rem solid var(--color-theme-sub);
  outline: none;
  box-sizing: border-box;
}
/* 数字框以前写的是未定义的 --color-border，等于没边框；现在跟随站点的主色描边 */
.config-item input:focus {
  border-color: var(--color-theme);
  color: #fff;
}
input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button {
  opacity: 1 !important;
  display: block !important;
  height: auto !important;
}


.x-sign {
  margin: 0 0.08rem;
  font-size: 0.18rem;
}

.check-item {
  gap: 0.12rem;
}

.config-item input[type="checkbox"] {
  width: 0.24rem;
  height: 0.24rem;
  cursor: pointer;
  /* 与「选曲列表」弹窗里的选框一致，用站点主色 */
  accent-color: var(--color-theme);
}

.btn-group-right {
  display: flex;
  gap: 0.12rem;
  flex-shrink: 0;
}

.gen-btn, .save-btn {
  padding: 0.1rem 0.2rem;
  font-size: 0.16rem;
  background: var(--color-btn);
  color: var(--color-text);
  border: none;
  cursor: pointer;
  white-space: nowrap;
}
.gen-btn:hover, .save-btn:hover {
  color: var(--color-btn-hover);
}
.gen-btn:disabled, .save-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.gen-btn:disabled:hover, .save-btn:disabled:hover {
  color: var(--color-text);
}

.main-content {
  display: flex;
  gap: 0.3rem;
  justify-content: center;
  align-items: flex-start;
  flex-wrap: wrap;
}

.grid-scroll-wrap,
.answer-scroll-wrap {
  width: 6.8rem;
  height: 6.8rem;
  background: var(--color-bg-sub);
  display: block;
  padding: 0;
  overflow: auto;
  cursor: grab;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.grid-scroll-wrap:active,
.answer-scroll-wrap:active {
  cursor: grabbing;
}
.grid-scroll-wrap::-webkit-scrollbar,
.answer-scroll-wrap::-webkit-scrollbar {
  display: none;
}

.grid, .answer-grid {
  display: grid;
  gap: 0;
  flex-shrink: 0;
  margin: 0 auto;
}
.cell, .answer-cell {
  width: 0.68rem;
  height: 0.68rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text);
  font-size: 0.22rem;
  border: none !important;
  box-sizing: border-box;
  background: rgba(255, 255, 255, 0.08);
}

.image-wrap-hidden {
  position: fixed;
  left: -9999px;
  padding: 0.2rem;
  background: #494949;
}
.grid-image-container {
  position: relative;
  width: fit-content;
  height: fit-content;
}
.grid-image {
  display: grid;
  gap: 0;
  position: relative;
  z-index: 1;
}
.cell-image {
  width: 0.68rem;
  height: 0.68rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.22rem;
}
</style>