<template>
  <div class="song-select-wrapper">
    <button class="open-btn" @click="showModal = true">
      选曲列表
    </button>

    <div class="modal-mask" v-if="showModal" @click.self="closeModal">
      <div class="modal-container">
        <div class="modal-header">
          <div class="header-left">
            <button class="header-btn" @click="showAddModal = true">添加</button>
            <button class="header-btn" @click="selectAll">全选</button>
            <button class="header-btn" @click="invertSelect">反选</button>
          </div>
          <div class="header-right">
            <button class="header-btn" @click="confirmSelect">确定</button>
            <button class="header-btn" @click="closeModal">取消</button>
          </div>
        </div>

        <div class="modal-body">
          <div class="song-grid">
            <label
              v-for="song in songList"
              :key="song.id"
              class="song-item"
            >
              <input
                type="checkbox"
                v-model="selectedIds"
                :value="song.id"
                class="song-checkbox"
              />
              <span class="song-name" :title="song.name">{{ song.name }}</span>
            </label>
          </div>
        </div>
      </div>
    </div>

    <div class="modal-mask" v-if="showAddModal" @click.self="closeAddModal">
      <div class="add-modal-container">
        <textarea
            v-model="newSongName"
            class="add-input"
            placeholder="请输入更多曲名（按行区分）"
            @keydown.enter.prevent="($event.shiftKey && addNewSong())"
        ></textarea>
        <div class="add-modal-footer">
          <button class="add-btn cancel" @click="closeAddModal">取消</button>
          <button class="add-btn confirm" @click="addNewSong">确认</button>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, defineEmits } from 'vue'
import axios from 'axios'

const emit = defineEmits(['selected-change'])

const showModal = ref(false)
const showAddModal = ref(false)
const songList = ref([])
const selectedIds = ref([])
const newSongName = ref('')

onMounted(async () => {
  try {
    const { data } = await axios.get('/files/infos/infos.json')
    const list = []

    for (const [id, info] of Object.entries(data)) {
      list.push({
        id,
        name: info.name || 'UNKNOWN',
        display: info.display !== false
      })
    }

    list.sort((a, b) => {
        const isChineseA = /^[\u4e00-\u9fa5]/.test(a.name.charAt(0))
        const isChineseB = /^[\u4e00-\u9fa5]/.test(b.name.charAt(0))

        if (!isChineseA && isChineseB) return -1
        if (isChineseA && !isChineseB) return 1

        return a.name.localeCompare(b.name)
    })

    songList.value = list
    selectedIds.value = list.filter(item => item.display).map(item => item.id)

    confirmSelect()
  } catch (err) {
    console.error('加载歌曲列表失败：', err)
  }
})

const closeModal = () => {
  showModal.value = false
}

const closeAddModal = () => {
  showAddModal.value = false
  newSongName.value = ''
}

const confirmSelect = () => {
  const selectedSongs = songList.value.filter(item => selectedIds.value.includes(item.id))
  emit('selected-change', {
    selectedIds: selectedIds.value,
    selectedSongs: selectedSongs
  })
  closeModal()
}

const selectAll = () => {
  selectedIds.value = songList.value.map(item => item.id)
}

const invertSelect = () => {
  const allIds = songList.value.map(item => item.id)
  selectedIds.value = allIds.filter(id => !selectedIds.value.includes(id))
}

const addNewSong = () => {
  const songNames = newSongName.value.split('\n').map(item => item.trim()).filter(Boolean)
  if (songNames.length === 0) {
    closeAddModal()
    return
  }

  const uniqueNames = [...new Set(songNames)]
  
  const newSongs = []
  for (const name of uniqueNames) {
    const isExist = songList.value.some(item => item.name === name)
    if (isExist) continue

    const newId = `custom_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`
    newSongs.push({
      id: newId,
      name: name,
      display: false 
    })
  }

  songList.value.push(...newSongs)
  
  songList.value.sort((a, b) => {
    const isChineseA = /^[\u4e00-\u9fa5]/.test(a.name.charAt(0))
    const isChineseB = /^[\u4e00-\u9fa5]/.test(b.name.charAt(0))

    if (!isChineseA && isChineseB) return -1
    if (isChineseA && !isChineseB) return 1

    return a.name.localeCompare(b.name)
  })
  
  closeAddModal()
}
</script>

<style scoped>
.song-select-wrapper {
  width: 100%;
  margin: 0.2rem 0;
}

.open-btn {
  padding: 0.06rem 0.16rem;
  font-size: 0.16rem;
  cursor: pointer;
  user-select: none;
  background: var(--color-btn);
  color: var(--color-text);
  display: flex;
  flex-wrap: wrap;
  border: 0.01rem solid var(--color-theme-sub);
}
.open-btn:hover {
  color: var(--color-btn-hover);
}

.modal-mask {
  position: fixed;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
}

.modal-container {
  --item-width: 3.7rem;
  --gap: 0.05rem;
  max-width: calc(var(--item-width) * 4 + var(--gap) * 3);
  width: 100%;
  background: var(--color-bg-main);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  max-height: 95%;
  border: none;
}

.modal-header {
  padding: 0.15rem 0.2rem;
  background: var(--color-bg-main);
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  flex-wrap: wrap;
  gap: 0.1rem;
  user-select: none;
}

.header-left,
.header-right {
  display: flex;
  gap: 0.1rem;
}

.header-btn {
  padding: 0.08rem 0.16rem;
  font-size: 0.14rem;
  background: var(--color-btn);
  color: var(--color-text);
  border: none;
  cursor: pointer;
  white-space: nowrap;
}
.header-btn:hover {
  color: var(--color-btn-hover);
}

.modal-body {
  padding: 0.1rem;
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--color-bg-main);
  box-sizing: border-box;
  user-select: none;
}
.modal-body::-webkit-scrollbar {
  display: none;
}

.song-grid {
  display: grid;
  grid-template-columns: repeat(4, var(--item-width));
  gap: var(--gap);
  justify-content: center;
  width: 100%;
  box-sizing: border-box;
  user-select: none;
}

.song-item {
  display: flex;
  align-items: center;
  border: none;
  cursor: pointer;
  font-size: 0.22rem;
  color: var(--color-text);
  width: var(--item-width);
  box-sizing: border-box;
  padding: 0.05rem 0.1rem;
  user-select: none;
}
.song-item:hover {
  color: var(--color-btn-hover);
}

.song-name {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.song-checkbox {
  accent-color: var(--color-theme);
  width: 0.22rem;
  height: 0.22rem;
  margin-right: 0.1rem;
  flex-shrink: 0;
}

.add-modal-container {
  width: 70%;
  height: 95%;
  background: var(--color-bg-main);
  padding: 0.2rem;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  position: relative;
}

.add-input {
  width: 100%;
  height: 95%;
  padding: 0.15rem;
  font-size: 0.2rem;
  background: var(--color-bg-sub);
  color: var(--color-text);
  outline: none;
  box-sizing: border-box;
  resize: none;
  font-family: inherit;
  white-space: pre-wrap;
  text-align: left;
  vertical-align: top;
}
.add-input::-webkit-scrollbar {
  display: none;
}

.add-modal-footer {
  position: absolute;
  right: 0.2rem;
  bottom: 0.1rem;
  display: flex;
  gap: 0.1rem;
}

.add-btn {
  padding: 0.1rem 0.3rem;
  font-size: 0.14rem;
  border: none;
  cursor: pointer;
  color: var(--color-text);
  user-select: none;
}
.add-btn:hover {
  color: var(--color-btn-hover);
}

.add-btn.confirm {
  background: var(--color-btn);
}
.add-btn.cancel {
  background: var(--color-btn);
}
</style>